const PI_TURN_ANCHORS_VERSION = 1
const PI_TURN_ANCHORS_FILE = 'pi-turn-anchors.json'

interface PiTurnAnchorsIndex {
  version: number
  anchors: Record<string, string>
}

function getPiTurnAnchorsPath(sessionPath: string): string {
  return join(sessionPath, 'meta', PI_TURN_ANCHORS_FILE)
}

export async function loadPiTurnAnchors(
  sessionPath: string,
  assertDestination?: () => void,
): Promise<PiTurnAnchorsIndex> {
  assertDestination?.()
  const filePath = getPiTurnAnchorsPath(sessionPath)
  let result: PiTurnAnchorsIndex
  try {
    const raw = await readFile(filePath, 'utf-8')
    const parsed = JSON.parse(raw) as Partial<PiTurnAnchorsIndex>
    const anchors = (parsed.anchors && typeof parsed.anchors === 'object') ? parsed.anchors : {}
    const normalized: Record<string, string> = {}
    for (const [messageId, anchor] of Object.entries(anchors)) {
      if (typeof messageId === 'string' && typeof anchor === 'string' && messageId && anchor) {
        normalized[messageId] = anchor
      }
    }
    result = {
      version: PI_TURN_ANCHORS_VERSION,
      anchors: normalized,
    }
  } catch {
    result = {
      version: PI_TURN_ANCHORS_VERSION,
      anchors: {},
    }
  }
  assertDestination?.()
  return result
}

async function getPiTurnAnchor(
  sessionPath: string,
  messageId: string,
  assertDestination?: () => void,
): Promise<string | undefined> {
  if (!messageId) return undefined
  const index = await loadPiTurnAnchors(sessionPath, assertDestination)
  return index.anchors[messageId]
}

export async function savePiTurnAnchor(
  sessionPath: string,
  messageId: string,
  anchorId: string,
  assertDestination?: () => void,
): Promise<void> {
  if (!messageId || !anchorId) return

  const index = await loadPiTurnAnchors(sessionPath, assertDestination)
  if (index.anchors[messageId] === anchorId) return

  index.anchors[messageId] = anchorId

  const filePath = getPiTurnAnchorsPath(sessionPath)
  assertDestination?.()
  await mkdir(join(sessionPath, 'meta'), { recursive: true })
  assertDestination?.()
  await writeFile(filePath, JSON.stringify(index), 'utf-8')
  assertDestination?.()
}

/**
 * Copy Pi turn anchors from the source session into the branch session,
 * filtered to the messages actually carried into the branch.
 *
 * Without this, branching a branch is silently lossy: the source branch's
 * sidecar contains no anchors for messages copied from its own parent, so a
 * downstream branch falls back to "full-history fork" — discarding the
 * branch cutoff and producing a session whose visible history doesn't match
 * what the LLM sees. See craft-agents-oss#782.
 */
export async function copyPiTurnAnchorsForBranch(
  sourceSessionPath: string,
  branchSessionPath: string,
  branchedMessageIds: Iterable<string>,
  assertSourceDestination?: () => void,
): Promise<void> {
  const index = await loadPiTurnAnchors(sourceSessionPath, assertSourceDestination)
  if (Object.keys(index.anchors).length === 0) return
  const idSet = new Set(branchedMessageIds)
  const filtered: Record<string, string> = {}
  for (const [messageId, anchor] of Object.entries(index.anchors)) {
    if (idSet.has(messageId)) {
      filtered[messageId] = anchor
    }
  }
  if (Object.keys(filtered).length === 0) return
  await mkdir(join(branchSessionPath, 'meta'), { recursive: true })
  await writeFile(
    getPiTurnAnchorsPath(branchSessionPath),
    JSON.stringify({ version: PI_TURN_ANCHORS_VERSION, anchors: filtered }),
    'utf-8',
  )
}

const CLAUDE_TURN_ANCHORS_VERSION = 1
const CLAUDE_TURN_ANCHORS_FILE = 'claude-turn-anchors.json'

interface ClaudeTurnAnchorRecord {
  sdkSessionId: string
  sdkMessageUuid: string
}

interface ClaudeTurnAnchorsIndex {
  version: number
  anchors: Record<string, ClaudeTurnAnchorRecord>
}

function getClaudeTurnAnchorsPath(sessionPath: string): string {
  return join(sessionPath, 'meta', CLAUDE_TURN_ANCHORS_FILE)
}

function isClaudeMessageUuid(turnId: string): boolean {
  return /^msg_[A-Za-z0-9]+$/.test(turnId)
}

async function loadClaudeTurnAnchors(
  sessionPath: string,
  assertDestination?: () => void,
): Promise<ClaudeTurnAnchorsIndex> {
  assertDestination?.()
  const filePath = getClaudeTurnAnchorsPath(sessionPath)
  let result: ClaudeTurnAnchorsIndex
  try {
    const raw = await readFile(filePath, 'utf-8')
    const parsed = JSON.parse(raw) as Partial<ClaudeTurnAnchorsIndex>
    const anchors = (parsed.anchors && typeof parsed.anchors === 'object') ? parsed.anchors : {}
    const normalized: Record<string, ClaudeTurnAnchorRecord> = {}

    for (const [messageId, value] of Object.entries(anchors)) {
      if (!messageId || typeof messageId !== 'string') continue
      if (!value || typeof value !== 'object') continue
      const sdkSessionId = (value as { sdkSessionId?: unknown }).sdkSessionId
      const sdkMessageUuid = (value as { sdkMessageUuid?: unknown }).sdkMessageUuid
      if (typeof sdkSessionId === 'string' && sdkSessionId && typeof sdkMessageUuid === 'string' && sdkMessageUuid) {
        normalized[messageId] = { sdkSessionId, sdkMessageUuid }
      }
    }

    result = {
      version: CLAUDE_TURN_ANCHORS_VERSION,
      anchors: normalized,
    }
  } catch {
    result = {
      version: CLAUDE_TURN_ANCHORS_VERSION,
      anchors: {},
    }
  }
  assertDestination?.()
  return result
}

async function getClaudeTurnAnchor(
  sessionPath: string,
  messageId: string,
  assertDestination?: () => void,
): Promise<ClaudeTurnAnchorRecord | undefined> {
  if (!messageId) return undefined
  const index = await loadClaudeTurnAnchors(sessionPath, assertDestination)
  return index.anchors[messageId]
}

async function saveClaudeTurnAnchor(
  sessionPath: string,
  messageId: string,
  sdkSessionId: string,
  sdkMessageUuid: string,
  assertDestination?: () => void,
): Promise<void> {
  if (!messageId || !sdkSessionId || !sdkMessageUuid) return

  const index = await loadClaudeTurnAnchors(sessionPath, assertDestination)
  const previous = index.anchors[messageId]
  if (previous && previous.sdkSessionId === sdkSessionId && previous.sdkMessageUuid === sdkMessageUuid) return

  index.anchors[messageId] = {
    sdkSessionId,
    sdkMessageUuid,
  }

  const filePath = getClaudeTurnAnchorsPath(sessionPath)
  assertDestination?.()
  await mkdir(join(sessionPath, 'meta'), { recursive: true })
  assertDestination?.()
  await writeFile(filePath, JSON.stringify(index), 'utf-8')
  assertDestination?.()
}

/**
 * Build MCP and API servers from sources using the new unified modules.
 * Handles credential loading and server building in one step.
 * When auth errors occur, updates source configs to reflect actual state.
 *
 * @param sources - Sources to build servers for
 * @param sessionPath - Optional path to session folder for saving large API responses
 * @param tokenRefreshManager - Optional TokenRefreshManager for OAuth token refresh
 */
interface BuildServersFromSourcesOptions {
  /** Discovery may inspect credentials and build transient clients, but it must
   * never refresh credentials or persist source/authentication state. */
  sourceStateMutation?: 'allow' | 'forbid'
  /** Exact source/config/credential generations sealed by an ordinary Mission
   * route. Presence (including an empty list) makes undeclared sources fail
   * closed and disables credential refresh for the sealed runtime. */
  ordinarySourceBindings?: readonly MissionOrdinarySourceBinding[]
}

async function buildServersFromSources(
  sources: LoadedSource[],
  sessionPath?: string,
  tokenRefreshManager?: TokenRefreshManager,
  summarize?: SummarizeCallback,
  assertCapabilities?: () => Promise<void>,
  capabilityLock?: MissionCapabilityLock,
  options?: BuildServersFromSourcesOptions,
) {
  const span = perf.span('sources.buildServers', { count: sources.length })
  const credManager = getSourceCredentialManager()
  const serverBuilder = getSourceServerBuilder()
  const ordinarySourceBindings = options?.ordinarySourceBindings
  const ordinarySourceBindingBySlug = ordinarySourceBindings === undefined
    ? undefined
    : new Map(ordinarySourceBindings.map(binding => [binding.slug, binding]))
  if (ordinarySourceBindings
    && ordinarySourceBindingBySlug!.size !== ordinarySourceBindings.length) {
    throw new Error('Ordinary Mission source binding set contains duplicate source slugs')
  }
  await assertCapabilities?.()
  const assertSourceBinding = async (
    source: LoadedSource,
    bound?: Awaited<ReturnType<typeof credManager.loadWithIdentity>>,
  ): Promise<void> => {
    const expected = capabilityLock?.capabilities.find(capability =>
      capability.kind === 'source' && capability.name === source.config.slug)
    if (capabilityLock && !expected) {
      throw new Error(`Specialized Mission source capability "${source.config.slug}" is not declared`)
    }
    await assertCapabilities?.()
    if (!expected) return
    const exactBound = bound === undefined ? await credManager.loadWithIdentity(source) : bound
    const actual = specializedSourceCapabilityBindingFromSnapshot(source, exactBound)
    if (actual.identitySha256 !== expected.identitySha256
      || actual.authorityBindingId !== expected.authorityBindingId) {
      throw new Error(`Specialized Mission source capability "${source.config.slug}" drifted`)
    }
  }
  const loadOrdinarySourceSnapshot = async (source: LoadedSource): Promise<{
    source: LoadedSource
    snapshot: Awaited<ReturnType<typeof credManager.loadRuntimeCredentialSnapshot>>
  } | undefined> => {
    if (!ordinarySourceBindingBySlug) return undefined
    const expected = ordinarySourceBindingBySlug.get(source.config.slug)
    if (!expected) {
      throw new Error(`Ordinary Mission source "${source.config.slug}" is not declared by its route lock`)
    }
    // Reload config + guide from disk and read the credential exactly once.
    // The same immutable snapshot is then both attested and injected into the
    // API call, so a rotated binding cannot be silently substituted.
    const liveSource = loadWorkspaceSources(source.workspaceRootPath)
      .find(candidate => candidate.config.enabled && candidate.config.slug === source.config.slug)
    if (!liveSource) {
      throw new Error(`Ordinary Mission source "${source.config.slug}" is unavailable or disabled`)
    }
    const snapshot = await credManager.loadRuntimeCredentialSnapshot(liveSource)
    const bound = snapshot.stored && snapshot.credentialId
      ? { credential: snapshot.stored, credentialId: snapshot.credentialId }
      : null
    const actual = specializedSourceCapabilityBindingFromSnapshot(liveSource, bound)
    if (actual.identitySha256 !== expected.identitySha256
      || actual.authorityBindingId !== expected.authorityBindingId) {
      throw new Error(`Ordinary Mission source "${source.config.slug}" credential binding drifted`)
    }
    return { source: liveSource, snapshot }
  }

  // Load identity + secret once per source. Under a capability lock the same
  // immutable value is used for validation and initial server construction.
  const sourcesWithCreds: SourceWithCredential[] = await Promise.all(
    sources.map(async (source) => {
      const ordinarySnapshot = await loadOrdinarySourceSnapshot(source)
      if (!capabilityLock && !ordinarySnapshot) return {
        source,
        token: await credManager.getToken(source),
        credential: await credManager.getApiCredential(source),
      }
      const exactSource = ordinarySnapshot?.source ?? source
      const snapshot = ordinarySnapshot?.snapshot
        ?? await credManager.loadRuntimeCredentialSnapshot(exactSource)
      const bound = snapshot.stored && snapshot.credentialId
        ? { credential: snapshot.stored, credentialId: snapshot.credentialId }
        : null
      if (capabilityLock) await assertSourceBinding(exactSource, bound)
      return { source: exactSource, token: snapshot.token, credential: snapshot.apiCredential }
    })
  )
  const initialCredentials = new Map(sourcesWithCreds.map(entry => [entry.source.config.slug, entry]))
  const sourceStateMutationForbidden = options?.sourceStateMutation === 'forbid'
  span.mark('credentials.loaded')

  // Build token getter for refreshable sources (OAuth + renew-endpoint)
  // Uses TokenRefreshManager for unified refresh logic (DRY principle)
  const getTokenForSource = (source: LoadedSource) => {
    const provider = source.config.provider
    // Provider-specific OAuth (Google, Slack, Microsoft) or generic OAuth (authType: 'oauth')
    if (isApiOAuthProvider(provider) || source.config.api?.authType === 'oauth') {
      if (ordinarySourceBindingBySlug) return async () => {
        const exact = await loadOrdinarySourceSnapshot(source)
        if (!exact?.snapshot.token) {
          throw new Error(`Ordinary Mission source "${source.config.slug}" has no valid bound token`)
        }
        return exact.snapshot.token
      }
      if (sourceStateMutationForbidden) return async () => {
        await assertCapabilities?.()
        const token = initialCredentials.get(source.config.slug)?.token
        if (!token) throw new Error(`Source "${source.config.slug}" has no token for read-only discovery`)
        return token
      }
      if (capabilityLock) return async () => {
        const snapshot = await credManager.loadRuntimeCredentialSnapshot(source)
        const bound = snapshot.stored && snapshot.credentialId
          ? { credential: snapshot.stored, credentialId: snapshot.credentialId }
          : null
        await assertSourceBinding(source, bound)
        if (!snapshot.token) throw new Error(`Specialized Mission source "${source.config.slug}" has no valid bound token`)
        return snapshot.token
      }
      const manager = tokenRefreshManager ?? new TokenRefreshManager(credManager, {
        log: (msg) => sessionLog.debug(msg),
      })
      const getToken = createTokenGetter(manager, source)
      return async () => {
        await assertSourceBinding(source)
        return getToken()
      }
    }
    // API renew endpoint — non-OAuth token refresh
    if (hasRenewEndpoint(source)) {
      if (ordinarySourceBindingBySlug) return async () => {
        const exact = await loadOrdinarySourceSnapshot(source)
        if (!exact?.snapshot.token) {
          throw new Error(`Ordinary Mission source "${source.config.slug}" has no valid bound token`)
        }
        return exact.snapshot.token
      }
      if (sourceStateMutationForbidden) return async () => {
        await assertCapabilities?.()
        const token = initialCredentials.get(source.config.slug)?.token
        if (!token) throw new Error(`Source "${source.config.slug}" has no token for read-only discovery`)
        return token
      }
      if (capabilityLock) return async () => {
        const snapshot = await credManager.loadRuntimeCredentialSnapshot(source)
        const bound = snapshot.stored && snapshot.credentialId
          ? { credential: snapshot.stored, credentialId: snapshot.credentialId }
          : null
        await assertSourceBinding(source, bound)
        if (!snapshot.token) throw new Error(`Specialized Mission source "${source.config.slug}" has no valid bound token`)
        return snapshot.token
      }
      const manager = tokenRefreshManager ?? new TokenRefreshManager(credManager, {
        log: (msg) => sessionLog.debug(msg),
      })
      const getToken = createTokenGetter(manager, source)
      return async () => {
        await assertSourceBinding(source)
        return getToken()
      }
    }
    return undefined
  }

  // Per-request credential getter for non-OAuth / non-renew API sources
  // (bearer / header / query / basic auth).
  //
  // Without this, the in-process API tool captures the credential as a static
  // string at build time and keeps using it forever — meaning a fresh JWT
  // entered via source_credential_prompt is ignored until session restart.
  //
  // With this getter, every API call reads the latest credential from the
  // vault, so credential updates take effect on the next call. OAuth and
  // renew-endpoint sources have their own refresh logic via TokenRefreshManager
  // and are skipped here.
  const getCredentialForSource = (source: LoadedSource) => {
    if (source.config.type !== 'api') return undefined
    if (source.config.api?.authType === 'none') return undefined
    if (isApiOAuthProvider(source.config.provider)) return undefined
    if (source.config.api?.authType === 'oauth') return undefined
    if (hasRenewEndpoint(source)) return undefined
    if (ordinarySourceBindingBySlug) return async () => {
      const exact = await loadOrdinarySourceSnapshot(source)
      if (!exact) throw new Error(`Ordinary Mission source "${source.config.slug}" is not sealed`)
      if (exact.snapshot.apiCredential === null) {
        throw new Error(`Ordinary Mission source "${source.config.slug}" has no valid bound credential`)
      }
      return exact.snapshot.apiCredential
    }
    if (sourceStateMutationForbidden) return async () => {
      await assertCapabilities?.()
      return initialCredentials.get(source.config.slug)?.credential ?? null
    }
    return async () => {
      if (capabilityLock) {
        const snapshot = await credManager.loadRuntimeCredentialSnapshot(source)
        const bound = snapshot.stored && snapshot.credentialId
          ? { credential: snapshot.stored, credentialId: snapshot.credentialId }
          : null
        await assertSourceBinding(source, bound)
        return snapshot.apiCredential
      }
      await assertCapabilities?.()
      const bound = await credManager.getApiCredentialWithIdentity(source)
      return bound?.credential ?? null
    }
  }

  // Pass sessionPath to enable saving large API responses to session folder
  const result = await serverBuilder.buildAll(
    sourcesWithCreds,
    getTokenForSource,
    sessionPath,
    summarize,
    getCredentialForSource,
  )
  span.mark('servers.built')
  span.setMetadata('mcpCount', Object.keys(result.mcpServers).length)
  span.setMetadata('apiCount', Object.keys(result.apiServers).length)

  // Update source configs for auth errors so UI reflects actual state.
  // Re-classify AUTH_REQUIRED → TOKEN_EXPIRED when the credential is merely
  // expired-but-refreshable; in that case the refresh cycle handles recovery
  // and we must NOT prematurely mark the source as needing re-auth (#710).
  if (!sourceStateMutationForbidden) {
    for (const error of result.errors) {
      if (error.error !== SERVER_BUILD_ERRORS.AUTH_REQUIRED) continue
      const source = sources.find(s => s.config.slug === error.sourceSlug)
      if (!source) continue

      if (capabilityLock) continue
      const cred = await credManager.load(source)
      const isExpiredRefreshable =
        cred &&
        (credManager.isExpired(cred) || credManager.needsRefresh(cred)) &&
        (cred.refreshToken || hasRenewEndpoint(source))

      if (isExpiredRefreshable) {
        error.error = SERVER_BUILD_ERRORS.TOKEN_EXPIRED
        sessionLog.debug(`Source ${error.sourceSlug}: TOKEN_EXPIRED — refresh cycle will handle`)
        continue
      }

      credManager.markSourceNeedsReauth(source, 'Token missing or expired')
      sessionLog.info(`Marked source ${error.sourceSlug} as needing re-auth`)
    }
  }

  span.end()
  return result
}

/**
 * Result of expired-credential refresh.
 */
interface RefreshExpiredCredentialsResult {
  /** Number of sources whose tokens were successfully refreshed */
  refreshedCount: number
  /** Sources that failed to refresh (for warning display) */
  failedSources: Array<{ slug: string; reason: string }>
}

/**
 * Refresh expired OAuth / renew-endpoint tokens for the given sources.
 *
 * Side effects (carried by `TokenRefreshManager.ensureFreshToken`):
 * - Success: source.config.isAuthenticated = true (in-memory + on disk).
 * - Failure: source.config.isAuthenticated = false + connectionStatus = 'needs_auth'
 *   (in-memory + on disk), so isSourceUsable() returns false and the source is
 *   excluded from intendedSlugs by callers.
 *
 * The caller is responsible for building servers AFTER this returns — that way
 * a single fresh build sees the correct credentials and the correct usable set.
 * Issue #710.
 */
async function refreshExpiredCredentials(
  sources: LoadedSource[],
  tokenRefreshManager: TokenRefreshManager
): Promise<RefreshExpiredCredentialsResult> {
  sessionLog.debug('[OAuth] Checking if any tokens need refresh')

  const needRefresh = await tokenRefreshManager.getSourcesNeedingRefresh(sources)
  if (needRefresh.length === 0) {
    return { refreshedCount: 0, failedSources: [] }
  }

  sessionLog.debug(`[OAuth] Refreshing ${needRefresh.length} source(s): ${needRefresh.map(s => s.config.slug).join(', ')}`)

  const { refreshed, failed } = await tokenRefreshManager.refreshSources(needRefresh)

  const failedSources = failed.map(({ source, reason }) => ({
    slug: source.config.slug,
    reason,
  }))

  return { refreshedCount: refreshed.length, failedSources }
}

/**
 * Apply bridge-mcp-server updates for backends that use it.
 * Delegates to the backend's own applyBridgeUpdates() method.
 * Each backend handles its own strategy via applyBridgeUpdates().
 */
async function applyBridgeUpdates(
  agent: AgentInstance,
  sessionPath: string,
  enabledSources: LoadedSource[],
  mcpServers: Record<string, import('@craft-agent/shared/agent/backend').SdkMcpServerConfig>,
  sessionId: string,
  workspaceRootPath: string,
  context: string,
  poolServerUrl?: string
): Promise<void> {
  await agent.applyBridgeUpdates({
    sessionPath,
    enabledSources,
    mcpServers,
    sessionId,
    workspaceRootPath,
    context,
    poolServerUrl,
  })
}

export async function commitRevocableSourceActivationRuntime(input: {
  isCurrent: () => boolean
  applyBridge: () => Promise<void>
  applyServers: () => Promise<void>
  restorePrevious: (stage: 'bridge-error' | 'bridge-superseded' | 'servers-error' | 'servers-superseded') => Promise<void>
  quarantine: () => Promise<void>
}): Promise<'committed' | 'superseded' | 'failed' | 'quarantined'> {
  const restore = async (
    stage: 'bridge-error' | 'bridge-superseded' | 'servers-error' | 'servers-superseded',
    fallback: 'superseded' | 'failed',
  ): Promise<'superseded' | 'failed' | 'quarantined'> => {
    try {
      await input.restorePrevious(stage)
      return fallback
    } catch {
      await input.quarantine()
      return 'quarantined'
    }
  }
  if (!input.isCurrent()) return 'superseded'
  try {
    await input.applyBridge()
  } catch {
    return restore('bridge-error', 'failed')
  }
  if (!input.isCurrent()) {
    return restore('bridge-superseded', 'superseded')
  }
  try {
    await input.applyServers()
  } catch {
    return restore('servers-error', 'failed')
  }
  if (!input.isCurrent()) {
    return restore('servers-superseded', 'superseded')
  }
  return 'committed'
}

/**
 * Resolve tool display metadata for a tool call.
 * Returns metadata with base64-encoded icon for viewer compatibility.
 *
 * @param toolName - Tool name from the event (e.g., "Skill", "mcp__linear__list_issues")
 * @param toolInput - Tool input (used for Skill tool to get skill identifier)
 * @param workspaceRootPath - Path to workspace for loading skills/sources
 * @param sources - Loaded sources for the workspace
 */
const BROWSER_TOOL_ICON_FILENAME = 'chrome.svg'
let browserToolIconDataUrlCache: string | null | undefined

async function getBrowserToolIconDataUrl(): Promise<string | undefined> {
  // Cache miss sentinel: undefined means "not computed yet"
  if (browserToolIconDataUrlCache !== undefined) {
    return browserToolIconDataUrlCache ?? undefined
  }

  try {
    const iconCandidates = [
      join(getToolIconsDir(), BROWSER_TOOL_ICON_FILENAME),
      // Dev fallback (before sync to ~/.craft-agent/tool-icons)
      join(process.cwd(), 'apps', 'electron', 'resources', 'tool-icons', BROWSER_TOOL_ICON_FILENAME),
      // Packaged fallback (app resources)
      join(process.resourcesPath, 'tool-icons', BROWSER_TOOL_ICON_FILENAME),
    ]

    for (const iconPath of iconCandidates) {
      if (!existsSync(iconPath)) continue
      const encoded = await encodeIconToDataUrlAsync(iconPath, { resize: resizeIconBuffer })
      if (encoded) {
        browserToolIconDataUrlCache = encoded
        return encoded
      }
    }

    browserToolIconDataUrlCache = null
  } catch {
    browserToolIconDataUrlCache = null
  }

  return browserToolIconDataUrlCache ?? undefined
}

async function resolveToolDisplayMeta(
  toolName: string,
  toolInput: Record<string, unknown> | undefined,
  workspaceRootPath: string,
  sources: LoadedSource[]
): Promise<ToolDisplayMeta | undefined> {
  // Check if it's an MCP tool (format: mcp__<serverSlug>__<toolName>)
  if (toolName.startsWith('mcp__')) {
    const parts = toolName.split('__')
    if (parts.length >= 3) {
      const serverSlug = parts[1]
      const toolSlug = parts.slice(2).join('__')

      // Internal MCP server tools (session, docs)
      const internalMcpServers: Record<string, Record<string, string>> = {
        'session': {
          'SubmitPlan': 'Submit Plan',
          'call_llm': 'LLM Query',
          'config_validate': 'Validate Config',
          'skill_validate': 'Validate Skill',
          'mermaid_validate': 'Validate Mermaid',
          'source_test': 'Test Source',
          'source_oauth_trigger': 'OAuth',
          'source_google_oauth_trigger': 'Google Auth',
          'source_slack_oauth_trigger': 'Slack Auth',
          'source_microsoft_oauth_trigger': 'Microsoft Auth',
          'source_credential_prompt': 'Enter Credentials',
          'transform_data': 'Transform Data',
          'render_template': 'Render Template',
          'update_user_preferences': 'Update Preferences',
          'send_developer_feedback': 'Send Feedback',
          'browser_tool': 'Browser',
        },
        'craft-agents-docs': {
          'SearchCraftAgents': 'Search Docs',
        },
      }

      const internalServer = internalMcpServers[serverSlug]
      if (internalServer) {
        const displayName = internalServer[toolSlug]
        if (displayName) {
          const normalizedBrowserTool = normalizeBrowserToolName(toolSlug)
          return {
            displayName,
            iconDataUrl: normalizedBrowserTool ? await getBrowserToolIconDataUrl() : undefined,
            category: 'native' as const,
          }
        }
      }

      // External source tools
      let sourceSlug = serverSlug

      // Special case: api-bridge server embeds source slug in tool name as "api_{slug}"
      // e.g., mcp__api-bridge__api_stripe → sourceSlug = "stripe"
      if (sourceSlug === 'api-bridge' && toolSlug.startsWith('api_')) {
        sourceSlug = toolSlug.slice(4)
      }

      const source = sources.find(s => s.config.slug === sourceSlug)
      if (source) {
        // Try file-based icon first, fall back to emoji icon from config
        const iconDataUrl = source.iconPath
          ? await encodeIconToDataUrlAsync(source.iconPath, { resize: resizeIconBuffer })
          : getEmojiIcon(source.config.icon)
        return {
          displayName: source.config.name,
          iconDataUrl,
          description: source.config.tagline,
          category: 'source' as const,
        }
      }
    }
    return undefined
  }

  // Check if it's the Skill tool
  if (toolName === 'Skill' && toolInput) {
    // Skill input has 'skill' param with format: "skillSlug" or "workspaceId:skillSlug"
    const skillParam = toolInput.skill as string | undefined
    if (skillParam) {
      // Extract skill slug (remove workspace prefix if present)
      const skillSlug = skillParam.includes(':') ? skillParam.split(':').pop() : skillParam
      if (skillSlug) {
        // Load skills and find the one being invoked
        try {
          const skills = loadAllSkills(workspaceRootPath)
          const skill = skills.find(s => s.slug === skillSlug)
          if (skill) {
            // Try file-based icon first, fall back to emoji icon from metadata
            const iconDataUrl = skill.iconPath
              ? await encodeIconToDataUrlAsync(skill.iconPath, { resize: resizeIconBuffer })
              : getEmojiIcon(skill.metadata.icon)
            return {
              displayName: skill.metadata.name,
              iconDataUrl,
              description: skill.metadata.description,
              category: 'skill' as const,
            }
          }
        } catch {
          // Skills loading failed, skip
        }
      }
    }
    return undefined
  }

  // CLI tool icon resolution for Bash commands
  // Parses the command string to detect known tools (git, npm, docker, etc.)
  // and resolves their brand icon from ~/.craft-agent/tool-icons/
  if (toolName === 'Bash' && toolInput?.command) {
    try {
      const toolIconsDir = getToolIconsDir()
      const match = resolveToolIcon(String(toolInput.command), toolIconsDir)
      if (match) {
        return {
          displayName: match.displayName,
          iconDataUrl: match.iconDataUrl,
          category: 'native' as const,
        }
      }
    } catch {
      // Icon resolution is best-effort — never crash the session for it
    }
  }

  // Native browser tool names (with Chrome icon)
  const normalizedBrowserToolName = normalizeBrowserToolName(toolName)
  if (normalizedBrowserToolName) {
    const browserDisplayName = normalizedBrowserToolName
      .split('_')
      .map((part, index) => (index === 0 ? part : part.charAt(0).toUpperCase() + part.slice(1)))
      .join(' ')
      .replace(/^browser\s+/i, 'Browser ')

    return {
      displayName: browserDisplayName,
      iconDataUrl: await getBrowserToolIconDataUrl(),
      category: 'native' as const,
    }
  }

  // Native tool display names (no icons - UI handles these with built-in icons)
  // This ensures toolDisplayMeta is always populated for consistent display
  const nativeToolNames: Record<string, string> = {
    'Read': 'Read',
    'Write': 'Write',
    'Edit': 'Edit',
    'Bash': 'Terminal',
    'Grep': 'Search',
    'Glob': 'Find Files',
    'Task': 'Agent',
    'Agent': 'Agent',
    'WebFetch': 'Fetch URL',
    'WebSearch': 'Web Search',
    'TodoWrite': 'Update Todos',
    'NotebookEdit': 'Edit Notebook',
    'KillShell': 'Kill Shell',
    'TaskOutput': 'Task Output',
  }

  const nativeDisplayName = nativeToolNames[toolName]
  if (nativeDisplayName) {
    return {
      displayName: nativeDisplayName,
      category: 'native' as const,
    }
  }

  // Unknown tool - no display metadata (will fall back to tool name in UI)
  return undefined
}

/** Agent type - unified backend interface for all providers */
type AgentInstance = AgentBackend

interface CostControlledTurnContext {
  message: string
  messageId: string
  options?: SendMessageOptions
}

/**
 * Status of a background task in the main-process registry.
 * - `running`   — backgrounded and no terminal notification seen yet.
 * - `completed`/`failed`/`stopped` — a real SDK task_notification arrived.
 * - `orphaned`  — the turn that owned the task ended before a terminal
 *   notification arrived. With the (default) per-turn subprocess model the task
 *   almost certainly died with the subprocess, so reporting it as still
 *   "running" would be a lie. Once WS2 keep-alive is enabled these are no longer
 *   produced because the query outlives the turn.
 */
type BackgroundTaskStatus = 'running' | 'completed' | 'failed' | 'stopped' | 'orphaned'

/** A background task tracked from launch, for cross-subprocess status queries. */
interface RunningBackgroundTask {
  taskId: string
  toolUseId?: string
  intent?: string
  /** ms timestamp when the task was backgrounded */
  startTime: number
  /** ms timestamp of the last task_progress notification, if any */
  lastProgressAt?: number
  /** elapsed seconds from the most recent progress notification, if any */
  elapsedSeconds?: number
  status: BackgroundTaskStatus
  /** ms timestamp when the task reached a terminal/orphaned status */
  completedAt?: number
  /** turn that launched the task (used to orphan on that turn's completion) */
  turnId?: string
  /** Workflow run id (wf_...) — set when this task is a Workflow launch. */
  workflowId?: string
  /** Count of workflow sub-agents completed so far (Workflow tasks only). */
  agentsCompleted?: number
}

interface RuntimeGenerationTelemetryRef {
  generationId: string
  turnId: string
  /** Captured before routing metadata is cleared by the completed message. */

}

interface RuntimeCompactionTelemetry {
  startedAt: number
  inputTokens?: number
  turnId?: string
  generationId?: string
}

interface ManagedSession {
  id: string
  workspace: Workspace
  /** Physical root captured when this runtime session was created. */
  readonly persistenceRootPath: string
  /** Device/inode proof preventing same-path workspace replacement. */
  readonly persistenceRootIdentity: SessionPersistenceRootIdentity
  /** Original lexical root used only for exact legacy project-memory scope keys. */
  readonly legacyProjectMemoryRootPath: string
  agent: AgentInstance | null  // Lazy-loaded - null until first message
  messages: Message[]
  isProcessing: boolean
  /** Set when user requests stop - allows event loop to drain before clearing isProcessing */
  stopRequested?: boolean
  lastMessageAt: number
  /** Last time this process used the lazily-created agent/MCP runtime. */
  runtimeLastActiveAt?: number
  streamingText: string
  // Incremented each time a new message starts processing.
  // Used to detect if a follow-up message has superseded the current one (stale-request guard).
  processingGeneration: number
  /** Generation that emitted a terminal provider error before its trailing complete event. */
  terminalErrorGeneration?: number
  /** Runtime receipts; explicit wait cursors also survive model compaction/restart. */
  waitCursors?: Record<string, string>
  lastWaitCompletion?: { generation: number; event: SessionCompletionEvent }
  /** Runtime transcript boundary for unverified diagnostics, never recovery authority. */
  waitDiagnosticBoundary?: WaitDiagnosticBoundary
  /** Generation intentionally ended so a newly activated source can restart the turn. */
  sourceActivationRestartGeneration?: number
  /** Runtime-only generation telemetry refs, keyed by processingGeneration. */
  executionTelemetryGenerations?: Map<number, RuntimeGenerationTelemetryRef>
  /** Runtime-only compaction spans, keyed by processingGeneration. */
  executionTelemetryCompactions?: Map<number, RuntimeCompactionTelemetry>
  /** Durable in-flight turn marker used for bounded automatic recovery. */
  pendingTurnRecovery?: PendingTurnRecovery
  /** Durable contract for the active user objective and its isolated budget. */
  pendingAgentDeliveryIds?: string[]
  pendingQueuedMessageIds?: string[]
  activeObjective?: ActiveSessionObjective
  userInputRequests?: UserInputRequest[]
  /** Durable Accept & Compact state; cleared atomically with an accepted user turn. */
  pendingPlanExecution?: {
    planPath: string
    draftInputSnapshot?: string
    awaitingCompaction: boolean
    executionDispatched?: boolean
  }
  /** Durable sensitive-action grants scoped to an exact category and target. */
  externalActionAuthorizations?: ExternalActionAuthorization[]
  // NOTE: Parent-child tracking state (pendingTools, parentToolStack, toolToParentMap,
  // pendingTextParent) has been removed. CraftAgent now provides parentToolUseId
  // directly on all events using the SDK's authoritative parent_tool_use_id field.
  // See: packages/shared/src/agent/tool-matching.ts
  // Session name (user-defined or AI-generated)
  name?: string
  isFlagged: boolean
  /** Whether this session is archived */
  isArchived?: boolean
  /** Recent autonomous-resolution evidence, persisted with the session. */
  autonomyEvents?: AutonomyEvent[]
  /** Browser fallback attempts already made during the current visible user turn. */
  autonomyFallbackAttemptedTools?: Set<string>
  /** Latest workspace policy waiting for the active provider stream to become idle. */
  pendingExternalActionPolicy?: ExternalActionPolicy
  /** Optional validated operational playbook bound to the session. */
  playbookSlug?: string
  /** Timestamp when session was archived (for retention policy) */
  archivedAt?: number
  /** Permission mode for this session ('safe', 'ask', 'allow-all') */
  permissionMode?: PermissionMode
  /** Previous permission mode (preserved across restarts for session_state modeTransition context) */
  previousPermissionMode?: PermissionMode
  /** Centralized MCP client pool for this session's source connections */
  mcpPool?: McpClientPool
  /** HTTP MCP server exposing pool tools to external SDK subprocesses */
  poolServer?: McpPoolServer
  // SDK session ID for conversation continuity
  sdkSessionId?: string
  // Token usage for display
  tokenUsage?: {
    inputTokens: number
    outputTokens: number
    totalTokens: number
    contextTokens: number
    costUsd: number
    cacheReadTokens?: number
    cacheCreationTokens?: number
    /** Model's context window size in tokens (from SDK modelUsage) */
    contextWindow?: number
  }
  // Session status (user-controlled) - determines open vs closed
  // Dynamic status ID referencing workspace status config
  sessionStatus?: string
  // Read/unread tracking - ID of last message user has read
  lastReadMessageId?: string
  /**
   * Explicit unread flag - single source of truth for NEW badge.
   * Set to true when assistant message completes while user is NOT viewing.
   * Set to false when user views the session (and not processing).
   */
  hasUnread?: boolean
  // Per-session source selection (slugs of enabled sources)
  enabledSourceSlugs?: string[]
  // Runtime provenance: true when enabledSourceSlugs is a materialized
  // workspace default rather than an explicit session selection. Never
  // persist the materialized array or an unrelated metadata write would
  // silently freeze a formerly dynamic workspace fallback.
  inheritsWorkspaceSourceSlugs?: boolean
  // Labels applied to this session (additive tags, many-per-session)
  labels?: string[]
  // Workspace-scoped project binding (undefined = unbound)
  projectId?: string
  // Parent session id — when set, this session is a subtask of the parent (undefined = top-level task)
  delegation?: SessionDelegation
  parentSessionId?: string
  // Kanban board column id ('todo' | 'in-progress' | 'done'); independent of sessionStatus
  kanbanColumn?: string
  // Tasks Conductor: slug of the task spec this session belongs to (orchestrator + child nodes)
  taskSlug?: string
  // Tasks Conductor: id of the run that spawned this child session (child nodes only)
  taskRunId?: string
  // Tasks Conductor: id of the DAG node this child session executes (child nodes only)
  taskNodeId?: string
  // Tasks Conductor: total DAG node count (orchestrator only) — stable board progress denominator
  taskNodeCount?: number
  // Tasks Conductor: hidden generate-time orchestrator awaiting validated adoption (off the board)
  taskDraft?: boolean
  // Host-enforced tool isolation envelope for a Conductor child session
  executionIsolation?: import('@craft-agent/shared/tasks').SessionExecutionIsolation
  // Mission Orchestration v2 durable ownership and dispatch identity
  missionId?: string
  missionWorkItemId?: string
  missionDispatchId?: string
  missionRole?: 'planner' | 'worker' | 'reviewer' | 'supervisor'
  missionRouteLockSha256?: string
  missionOrdinaryRouteLock?: MissionOrdinaryRouteLock
  missionCapabilityLock?: MissionCapabilityLock
  /** Exact in-memory source config/guide snapshot consumed by the current governed turn. */
  missionTurnSourceSnapshot?: LoadedSource[]
  /** Exact skill bytes injected into the governed runtime; never re-opened by the model. */
  missionSealedSkillPackages?: Array<{ slug: string; name: string; content: string }>
  // Working directory for this session (used by agent for bash commands)
  workingDirectory?: string
  // SDK cwd for session storage - set once at creation, never changes.
  // Ensures SDK can find session transcripts regardless of workingDirectory changes.
  sdkCwd?: string
  // Shared viewer URL (if shared via viewer)
  sharedUrl?: string
  // Shared session ID in viewer (for revoke)
  sharedId?: string
  // Model to use for this session (overrides global config if set)
  model?: string
  // LLM connection slug for this session (locked after first message)
  llmConnection?: string
  // Durable provenance for a caller-selected connection. Router-selected
  // connections remain eligible for per-turn reevaluation.
  connectionRoutePinned?: boolean
  // Whether the connection is locked (cannot be changed after first agent creation)
  connectionLocked?: boolean
  // Thinking level for this session ('off', 'think', 'max')
  thinkingLevel?: ThinkingLevel
  // System prompt preset for mini agents ('default' | 'mini')
  systemPromptPreset?: 'default' | 'mini' | string
  // Role/type of the last message (for badge display without loading messages)
  lastMessageRole?: 'user' | 'assistant' | 'plan' | 'tool' | 'error'
  // ID of the last final (non-intermediate) assistant message - pre-computed for unread detection
  lastFinalMessageId?: string
  // Turn baseline: last final assistant message ID at turn start (runtime-only, not persisted)
  turnStartFinalMessageId?: string
  /** Runtime-only status written by automatic lifecycle; explicit changes replace it and win. */
  turnLifecycleManagedStatus?: string
  // External session metadata updates seen while processing (applied after turn stop)
  pendingExternalMetadata?: SessionHeader
  // Guard: suppress external metadata revert after programmatic writes (setSessionStatus/setSessionLabels).
  // fs.watch fires during atomic write (unlink+rename) and can read stale data, reverting in-memory state.
  _metadataWriteGuardUntil?: number
  // Whether an async operation is ongoing (sharing, updating share, revoking, title regeneration)
  // Used for shimmer effect on session title
  isAsyncOperationOngoing?: boolean
  // Preview of first user message (for sidebar display fallback)
  preview?: string
  // When the session was first created (ms timestamp from JSONL header)
  createdAt?: number
  // App build provenance (optional for legacy sessions)
  createdByApp?: SessionAppProvenance
  lastUsedByApp?: SessionAppProvenance
  // Total message count (pre-computed in JSONL header for fast list loading)
  messageCount?: number
  // Message queue for handling new messages while processing
  // When a message arrives during processing, we interrupt and queue
  messageQueue: Array<{
    message: string
    attachments?: FileAttachment[]
    storedAttachments?: StoredAttachment[]
    options?: SendMessageOptions
    messageId?: string  // Pre-generated ID for matching with UI
    optimisticMessageId?: string  // Frontend's ID for reliable event matching
  }>
  /** Runtime correlation for providers that accept a steer but later cannot deliver it. */
  pendingUserSteers?: Map<string, {
    queued: ManagedSession['messageQueue'][number]
    messageBefore?: string
    objectiveBefore?: ActiveSessionObjective
    objectiveAfter?: ActiveSessionObjective
    recoveryBefore?: PendingTurnRecovery
  }>
  // Map of shellId -> command for killing background shells
  backgroundShellCommands: Map<string, string>
  // Map of taskId -> output info for background task results
  backgroundTaskOutputs: Map<string, { outputFile: string; summary: string; status: string; completedAt: number }>
  // Registry of background tasks (running + recently-terminal) for this session.
  // Unlike backgroundTaskOutputs (which only stores COMPLETED tasks for output
  // retrieval), this tracks tasks from the moment they are backgrounded, so a
  // cross-subprocess "status?" query can enumerate what is actually live. The
  // SDK's in-subprocess task tools cannot answer this: their state dies with the
  // subprocess at turn end, so this main-process registry is the real source of
  // truth for background-task status. See RunningBackgroundTask.
  backgroundTaskRegistry: Map<string, RunningBackgroundTask>
  // Whether messages have been loaded from disk (for lazy loading)
  messagesLoaded: boolean
  // Pending auth request tracking (for unified auth flow)
  pendingAuthRequestId?: string
  pendingAuthRequest?: AuthRequest
  // Auth retry tracking (for mid-session token expiry)
  // Store last sent message/attachments to enable retry after token refresh
  lastSentMessage?: string
  lastSentAttachments?: FileAttachment[]
  lastSentStoredAttachments?: StoredAttachment[]
  lastSentOptions?: SendMessageOptions
  /** Runtime claim identity for a machine delivery. Unlike lastSentOptions,
   * this survives an accepted mid-turn human steer until the owning generation
   * stops and classifies the receipt. */
  activeAgentDelivery?: { deliveryId: string; generation: number }
  // Flag to prevent infinite retry loops (reset at start of each sendMessage)
  authRetryAttempted?: boolean
  // Flag indicating auth retry is in progress (to prevent complete handler from interfering)
  authRetryInProgress?: boolean
  // Whether this session is hidden from session list (e.g., mini edit sessions)
  hidden?: boolean
  branchFromMessageId?: string
  // Branch context strategy:
  // - sdk-fork: provider-level fork from parent SDK session
  // - seeded-fresh-session: fresh backend session seeded with transcript up to branch cutoff
  branchContextStrategy?: 'sdk-fork' | 'seeded-fresh-session'
  // Parent session's SDK session ID (used only when branchContextStrategy === 'sdk-fork')
  branchFromSdkSessionId?: string
  // Parent session's storage path (used only when branchContextStrategy === 'sdk-fork')
  branchFromSessionPath?: string
  // Parent session's sdkCwd — needed so the fork subprocess uses the correct
  // ~/.claude/projects/{cwd-hash}/ directory to find the parent's session file.
  branchFromSdkCwd?: string
  // SDK assistant message UUID at the branch point — used as resumeSessionAt
  // to trim the forked conversation at the branch point.
  branchFromSdkTurnId?: string
  // One-shot flag for seeded branch mode - set true after first turn seed injection.
  branchSeedApplied?: boolean
  // One-shot hidden summary injected on the first turn after a remote transfer.
  transferredSessionSummary?: string
  // Whether the transferred-session summary has already been injected.
  transferredSessionSummaryApplied?: boolean
  // Token refresh manager for OAuth token refresh with rate limiting
  tokenRefreshManager: TokenRefreshManager
  // Metadata for sessions created by automations
  triggeredBy?: { automationName?: string; event?: string; timestamp?: number }
  // Promise that resolves when the agent instance is ready (for title gen to await)
  agentReady?: Promise<void>
  agentReadyResolve?: () => void
  // Per-session env overrides for SDK subprocess (e.g., ANTHROPIC_BASE_URL).
  // Stored on managed session so it persists across agent recreations (auth-retry, etc.)
  envOverrides?: Record<string, string>
  // Runtime-affecting backend config signature captured when the live agent was created/refreshed.
  backendRuntimeSignature?: string
  /**
   * Signature over fields that cannot be propagated via `update_runtime_config`
   * (see `runtime-config.ts:buildRestartRequiredSignature`). When this drifts,
   * the agent must be disposed + recreated rather than refreshed in place.
   */
  backendRestartSignature?: string
  // Whether the previous turn was interrupted (for context injection on next message).
  // Ephemeral — not persisted to disk. Cleared after one-shot injection.
  wasInterrupted?: boolean
  /**
   * Runtime-only: Pi SDK message id → Craft assistant message id.
   * Populated when a `text_complete` arrives carrying `sdkMessageId`, and read
   * when the follow-up `pi_turn_anchor` event arrives (deferred by one microtask
   * so the SDK's session-manager has updated its leaf — see craft-agents-oss#782).
   * Capped at PI_SDK_MESSAGE_ID_CACHE_LIMIT to bound memory in long sessions.
   */
  piSdkMessageToCraftMessage?: Map<string, string>
  // Runtime-only: annotate the next assistant response with why a route changed.
  pendingRoutingReason?: 'manual-handoff' | 'session-connection' | 'router' | string
  /** Durable host provenance for manual and task-computed model pins. */
  modelRoutePinned?: boolean
  /** Durable host provenance for a reasoning-only override. */
  thinkingLevelPinned?: boolean
  // Runtime-only: extra routing audit details for the next assistant response.
  pendingRoutingMeta?: Partial<RoutingMeta>
  /** Versioned model/thinking/profile decision captured before UI metadata is cleared. */
  pendingRoutingDecision?: SelectionSnapshot
  /** Durable backoff state preventing repeated compaction work across queued turns and restarts. */
  contextCompactionAttempt?: ContextCompactionAttemptState
  /** Durable lower transcript bound for provider fallback/recovery after a context reset. */
  providerContextBoundaryMessageId?: string
  // Runtime-only: policy-authorized fallback candidates for the current turn.
  pendingRoutingFallbackConnectionSlugs?: string[]
  // Runtime-only: provider failure emitted as a stream event. The handoff is
  // deferred until the current iterator completes so disposing its runtime
  // cannot deadlock event processing.
  pendingRuntimeProviderFallback?: {
    error: Error
    generation: number
  }
  // Runtime-only: bounded fallback attempts and per-turn loop prevention.
  routingFallbackAttempts?: number
  routingAttemptedConnectionSlugs?: Set<string>
  // Runtime-only: consecutive connection failures and cooldown windows.

  // Source-activation auto-retry (craft-agents-oss#804). When a source activates
  // mid-turn, we re-send the original message with a "[<slug> activated]" suffix
  // after a short delay. The pending slot lets `sendMessage` reject a duplicate
  // RPC from a legacy renderer while authenticating the server-owned dispatch.
  autoRetryTimer?: ReturnType<typeof setTimeout>
  autoRetryPending?: {
    content: string
    rawMessage: string
    deadlineMs: number
    tombstoneExpiresAt: number
    /** Durable objective ancestry copied into the persisted internal origin. */
    objectiveId: string
    objectiveRevision: string
    sourceSlug: string
    sourceActivationId: string
    generation: number
    cancellationEpoch: number
    messageCountAtSchedule: number
    /** Runtime-only capability held by the server timer. Text equality is not authority. */
    dispatchToken: symbol
    /** A reversible claim prevents the timer from dispatching twice across awaits. */
    dispatchInFlight: boolean
    dispatchAttempts: number
    messageId?: string
    providerStarted?: boolean
    /** True only after the hidden row has crossed its first durability fence. */
    committed: boolean
    /** Timer/objective was superseded; retain exact text only as a dedup tombstone. */
    cancelled: boolean
  }
  /** Runtime dedup history for mixed-version renderer retries. Bounded by count
   * and TTL so A remains rejected after B without swallowing human text forever. */
  autoRetryTombstones?: Array<{ content: string; expiresAt: number }>
  /** Clean, pre-enrichment input owned by the exact provider generation. */
  sourceActivationTurn?: {
    generation: number
    cancellationEpoch: number
    rawMessage: string
    objectiveId: string
    objectiveRevision: string
  }
}

export type SessionReviewRole = Pick<ManagedSession, 'delegation' | 'missionRole'>

/** Mission v2 stores terminal reviewers on missionRole rather than the legacy
 * delegation envelope. Both provenances are host-owned and must produce the
 * same read-only routing, objective authority and permission boundary. */
export function isTerminalReviewSession(session: SessionReviewRole): boolean {
  return session.delegation?.role === 'reviewer'
    || session.missionRole === 'reviewer'
    || session.missionRole === 'supervisor'
}

type MissionRecoveryOwnership = SessionReviewRole & {
  missionId?: string
  missionWorkItemId?: string
  missionDispatchId?: string
  pendingTurnRecovery?: PendingTurnRecovery
}

/** MissionRuntime, not the generic cold-session scheduler, owns recovery of
 * every durably identified Mission turn. Only MissionRuntime can bind the
 * resumed provider work back to the exact journal dispatch and revalidate its
 * route/capability boundary. Restricting this ownership to reviewers lets a
 * worker race the generic restart scheduler and resume outside the journal. */
export function isMissionRuntimeOwnedRecovery(
  session: MissionRecoveryOwnership,
): boolean {
  return !!session.pendingTurnRecovery
    && !!session.missionId
    && !!session.missionWorkItemId
    && !!session.missionDispatchId
}

export function delegatedObjectiveRoleForSession(
  session: SessionReviewRole,
): 'worker' | 'reviewer' | undefined {
  return isTerminalReviewSession(session) ? 'reviewer' : session.delegation?.role
}

/** Rebuild the durable read-only envelope for reviewers created before the
 * Mission role clamp existed. Preserve a valid narrower read scope and its
 * resource bounds, but never carry write authority into a terminal review. */
export function terminalReviewExecutionIsolation(
  existing: SessionExecutionIsolation | undefined,
  workspaceRoot: string,
): SessionExecutionIsolation {
  const validExisting = existing
    && validateSessionExecutionIsolation(existing, workspaceRoot).allowed
    ? existing.policy
    : undefined
  return {
    effect: 'read',
    policy: {
      workspaceRoot: validExisting?.workspaceRoot ?? workspaceRoot,
      allowedReadPaths: [...(validExisting?.allowedReadPaths ?? ['.'])],
      allowedWritePaths: [],
      ...(validExisting?.allowedReadToolInvocations?.length ? {
        allowedReadToolInvocations: validExisting.allowedReadToolInvocations.map(invocation => ({
          toolName: invocation.toolName,
          inputJson: invocation.inputJson,
        })),
      } : {}),
      networkAccess: validExisting?.networkAccess ?? 'disabled',
      allowedHosts: [...(validExisting?.allowedHosts ?? [])],
      maxCpuPercent: validExisting?.maxCpuPercent ?? 100,
      maxMemoryMb: validExisting?.maxMemoryMb ?? 1024,
      timeoutMs: validExisting?.timeoutMs ?? 30 * 60 * 1000,
    },
  }
}

interface MissionToolPreflightInput {
  toolName: string
  toolInput: Record<string, unknown>
  permissionMode: PermissionMode
  enabledSourceSlugs?: string[]
}

type MissionToolPreflightDecision = { allowed: true } | { allowed: false; reason: string }
type MissionDeclaredToolCapabilities = NonNullable<
  ReturnType<McpClientPool['getProxyToolCapabilities']>
>
interface MissionLiveToolDefinition {
  capabilities: MissionDeclaredToolCapabilities
  /** Unmodified schema returned by the exact live MCP tools/list response. */
  inputSchema: Record<string, unknown>
}
type MissionSourceToolCatalogDecision =
  | { allowed: true; tools: Map<string, MissionLiveToolDefinition> }
  | { allowed: false; reason: string }
type MissionSourceToolCatalogCache = Map<string, Promise<MissionSourceToolCatalogDecision>>

const missionMcpInputValidator = new AjvJsonSchemaValidator()

const PI_SDK_MESSAGE_ID_CACHE_LIMIT = 256
const SOURCE_ACTIVATION_DEDUP_WINDOW_MS = 2_000
const SOURCE_ACTIVATION_TOMBSTONE_TTL_MS = 30_000
const SOURCE_ACTIVATION_TOMBSTONE_LIMIT = 8
const SOURCE_ACTIVATION_MAX_DISPATCH_ATTEMPTS = 2
const SOURCE_ACTIVATION_PROTOCOL_SUFFIX = /\n\n\[[a-z0-9](?:[a-z0-9-]{0,126}[a-z0-9])? activated\]$/

export interface AutoRetryPendingHost {
  autoRetryPending?: {
    content: string
    rawMessage: string
    deadlineMs: number
    tombstoneExpiresAt: number
    objectiveId: string
    objectiveRevision: string
    sourceSlug: string
    sourceActivationId: string
    generation: number
    cancellationEpoch: number
    messageCountAtSchedule: number
    dispatchToken: symbol
    dispatchInFlight: boolean
    dispatchAttempts: number
    messageId?: string
    providerStarted?: boolean
    committed: boolean
    cancelled: boolean
  }
  autoRetryTombstones?: Array<{ content: string; expiresAt: number }>
}

function pruneAutoRetryTombstones(host: AutoRetryPendingHost, nowMs: number): void {
  if (host.autoRetryTombstones?.length) {
    host.autoRetryTombstones = host.autoRetryTombstones
      .filter(tombstone => tombstone.expiresAt > nowMs)
      .slice(-SOURCE_ACTIVATION_TOMBSTONE_LIMIT)
  }
  const pending = host.autoRetryPending
  if (pending && pending.tombstoneExpiresAt <= nowMs) host.autoRetryPending = undefined
}

function rememberAutoRetryTombstone(
  host: AutoRetryPendingHost,
  content: string,
  nowMs = Date.now(),
  expiresAt = nowMs + SOURCE_ACTIVATION_TOMBSTONE_TTL_MS,
): void {
  pruneAutoRetryTombstones(host, nowMs)
  const retained = (host.autoRetryTombstones ?? []).filter(item => item.content !== content)
  retained.push({ content, expiresAt: Math.max(expiresAt, nowMs + 1) })
  host.autoRetryTombstones = retained.slice(-SOURCE_ACTIVATION_TOMBSTONE_LIMIT)
}

export function claimAutoRetryPending(
  host: AutoRetryPendingHost,
  message: string,
  nowMs = Date.now(),
  dispatchToken?: symbol,
): 'send' | 'authenticated' | 'drop' | 'reserved' {
  pruneAutoRetryTombstones(host, nowMs)
  const pending = host.autoRetryPending
  if (pending && message === pending.content) {
    // A mixed-version renderer can replay the exact suffix, and a human can
    // type identical text. Only the one-shot server capability may turn that
    // text into a hidden continuation of the existing objective. Authenticate
    // it even if the event loop delayed the nominal 100 ms timer past the
    // duplicate-suppression deadline.
    if (dispatchToken === pending.dispatchToken) {
      if (pending.committed || pending.cancelled || pending.dispatchInFlight) return 'drop'
      pending.dispatchInFlight = true
      return 'authenticated'
    }
    // Keep the exact-text tombstone after the latency window. A delayed legacy
    // renderer must never turn this host-authored marker into a visible user
    // turn (and therefore a new objective root) merely because 2s elapsed.
    return 'drop'
  }
  if (host.autoRetryTombstones?.some(tombstone => tombstone.content === message)) return 'drop'
  // This exact terminal suffix is host protocol, never direct-user authority.
  // Quoted/non-terminal mentions remain ordinary human text.
  if (SOURCE_ACTIVATION_PROTOCOL_SUFFIX.test(message)) return 'reserved'
  return 'send'
}

type SourceActivationOrigin = NonNullable<SendMessageOptions['internalOrigin']> & {
  kind: 'source-activation'
  objectiveId: string
  objectiveRevision: string
  sourceSlug: string
  sourceActivationId: string
}

function sourceActivationObjectiveBinding(
  objective: ActiveSessionObjective | undefined,
): Pick<SourceActivationOrigin, 'objectiveId' | 'objectiveRevision'> | undefined {
  if (!objective || objective.terminalState !== 'active') return undefined
  const objectiveId = objective.objectiveId ?? objective.userMessageId
  const objectiveRevision = objective.lastUserMessageId ?? objective.userMessageId
  return objectiveId && objectiveRevision ? { objectiveId, objectiveRevision } : undefined
}

function isSourceActivationOriginCurrent(
  objective: ActiveSessionObjective | undefined,
  origin: NonNullable<SendMessageOptions['internalOrigin']> | undefined,
): origin is SourceActivationOrigin {
  if (origin?.kind !== 'source-activation'
    || !origin.objectiveId || !origin.objectiveRevision
    || !origin.sourceSlug || !origin.sourceActivationId) return false
  const current = sourceActivationObjectiveBinding(objective)
  return !!current && current.objectiveId === origin.objectiveId
    && current.objectiveRevision === origin.objectiveRevision
}

export interface SourceActivationRestartHost {
  sourceActivationRestartGeneration?: number
}

